using UnityEngine;

// Common rules for every mouse surface. Do not edit this file to add a surface:
// copy Surface_SimulationSensor_Template_1_0.cs instead.
//
// A surface answers two questions:
//   1. How high is the surface at each point?  -> BuildHeightsMM fills a square height map, in mm.
//   2. How much light does it reflect?          -> Reflectance (matte, 0..1).
// The height map is one square tile (Texels x Texels points, TexelMM apart) that repeats over the
// whole surface, so a surface pattern must repeat cleanly at the tile edges.
public abstract class Surface_SimulationSensor_Base_1_0 : ScriptableObject
{
    public const int Texels = 1024;                 // points per side of the tile
    public const float TexelMM = 0.004f;            // 4 um between points
    public const float TileMM = Texels * TexelMM;   // 4.096 mm tile

    [Header("Light")]
    [Tooltip("Share of light the surface reflects (matte). 0 = black, 1 = perfect white.")]
    [SerializeField, Range(0.0f, 1.0f)] protected float reflectance = 0.8f;

    [Header("Surface Results (calculated - edits are ignored)")]
    [SerializeField] protected float heightMinMM;
    [SerializeField] protected float heightMaxMM;
    [SerializeField] protected float roughnessRmsResultMM;

    [System.NonSerialized] private Texture2D _tex;
    [System.NonSerialized] private int _version = 1;
    [System.NonSerialized] private int _builtVersion = 0;
    [System.NonSerialized] private float _builtMmToUnit = -1.0f;

    public float Reflectance => reflectance;
    public float HeightMinMM => heightMinMM;
    public float HeightMaxMM => heightMaxMM;
    public float RoughnessRmsResultMM => roughnessRmsResultMM;
    public int Version => _version;

    // Fill h (Texels x Texels, row by row: index = z * Texels + x) with heights in mm.
    // Point (x, z) sits at x * TexelMM, z * TexelMM inside the tile.
    protected abstract void BuildHeightsMM(float[] h, int n, float texelMM);

    protected virtual void OnValidate()
    {
        _version++;
    }

    // Height map in scene units, mean height 0. Rebuilt only when a value of the surface changed.
    public Texture2D GetHeightMap(float mmToUnit)
    {
        if (_tex != null && _builtVersion == _version && _builtMmToUnit == mmToUnit) return _tex;

        int n = Texels;
        float[] h = new float[n * n];
        BuildHeightsMM(h, n, TexelMM);

        double sum = 0.0;
        for (int k = 0; k < h.Length; k++) sum += h[k];
        float mean = (float)(sum / h.Length);

        float hMin = float.MaxValue, hMax = float.MinValue;
        double sum2 = 0.0;
        for (int k = 0; k < h.Length; k++)
        {
            float mm = h[k] - mean;
            sum2 += mm * mm;
            if (mm < hMin) hMin = mm;
            if (mm > hMax) hMax = mm;
            h[k] = mm * mmToUnit;
        }
        // A perfectly flat surface still needs a thin layer for the ray tracer to hit.
        if (hMax - hMin < 0.00002f) { hMin -= 0.00001f; hMax += 0.00001f; }

        if (_tex == null)
        {
            _tex = new Texture2D(n, n, TextureFormat.RFloat, false, true)
            {
                wrapMode = TextureWrapMode.Repeat,
                filterMode = FilterMode.Bilinear,
                hideFlags = HideFlags.HideAndDontSave
            };
        }
        _tex.SetPixelData(h, 0);
        _tex.Apply(false);

        heightMinMM = hMin;
        heightMaxMM = hMax;
        roughnessRmsResultMM = (float)System.Math.Sqrt(sum2 / h.Length);
        _builtVersion = _version;
        _builtMmToUnit = mmToUnit;
        return _tex;
    }

    protected virtual void OnDisable()
    {
        if (_tex != null) { DestroyImmediate(_tex); _tex = null; }
        _builtVersion = 0;
    }

    // Wraps an index into 0..n-1, so patterns repeat across tile edges.
    protected static int Wrap(int i, int n)
    {
        return ((i % n) + n) % n;
    }

    // Scales heights so their RMS equals targetRmsMM (mean removed first).
    protected static void ScaleToRms(float[] h, float targetRmsMM)
    {
        double sum = 0.0;
        for (int k = 0; k < h.Length; k++) sum += h[k];
        float mean = (float)(sum / h.Length);
        double sum2 = 0.0;
        for (int k = 0; k < h.Length; k++) { float d = h[k] - mean; sum2 += d * d; }
        float rms = (float)System.Math.Sqrt(sum2 / h.Length);
        if (rms < 1e-12f) return;
        float s = targetRmsMM / rms;
        for (int k = 0; k < h.Length; k++) h[k] = (h[k] - mean) * s;
    }
}
